package co.com.empresa.infrastructure.repository.typecategory;import co.com.empresa.domain.typecategory.TypeCategory;import co.com.empresa.infrastructure.adapters.output.repositories.command.typeCategory.ITypeCategoryCommandJpaRepository;import co.com.empresa.infrastructure.adapters.output.repositories.query.typeCategory.ITypeCategoryQueryJpaRepository;import co.com.empresa.infrastructure.entities.typeCategory.TypeCategoryEntity;import co.com.empresa.infrastructure.typecategory.TypeCategoryInfrastructureMapper;import co.com.empresa.infrastructure.typecategory.TypeCategoryRepositoryImpl;import org.junit.jupiter.api.BeforeEach;import org.junit.jupiter.api.DisplayName;import org.junit.jupiter.api.Test;import org.junit.jupiter.api.extension.ExtendWith;import org.mockito.InjectMocks;import org.mockito.Mock;import org.mockito.junit.jupiter.MockitoExtension;import java.time.LocalDateTime;import java.util.Optional;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.ArgumentMatchers.any;import static org.mockito.Mockito.verify;import static org.mockito.Mockito.when;@ExtendWith(MockitoExtension.class)class TypeCategoryRepositoryTest {    @Mock    private ITypeCategoryQueryJpaRepository queryJpaRepository;    @Mock    private ITypeCategoryCommandJpaRepository commandJpaRepository;    @Mock    private TypeCategoryInfrastructureMapper mapper;    @InjectMocks    private TypeCategoryRepositoryImpl typeCategoryRepository;    private TypeCategory typeCategoryModel;    private TypeCategoryEntity typeCategoryEntity;    @BeforeEach    void setUp() {        typeCategoryModel = TypeCategory.builder()                .id(1L)                .name("Test Category")                .code("CAT-001")                .description("Test Description")                .active(true)                .build();        typeCategoryEntity = TypeCategoryEntity.builder()                .id(1L)                .name("Test Category")                .code("CAT-001")                .description("Test Description")                .active(true)                .createBy("system")                .createDate(LocalDateTime.now())                .build();    }    @Test    @DisplayName("save: Should persist category and return mapped model")    void save_Success() {        when(mapper.modelToEntity(any())).thenReturn(typeCategoryEntity);        when(commandJpaRepository.save(any())).thenReturn(typeCategoryEntity);        when(mapper.entityToModel(any())).thenReturn(typeCategoryModel);        TypeCategory result = typeCategoryRepository.save(typeCategoryModel);        assertNotNull(result);        verify(commandJpaRepository).save(any());    }    @Test    @DisplayName("findById: Should return model when entity exists")    void findById_Exists_ReturnsModel() {        Long id = 1L;        when(queryJpaRepository.findById(id)).thenReturn(Optional.of(typeCategoryEntity));        when(mapper.entityToModel(typeCategoryEntity)).thenReturn(typeCategoryModel);        Optional<TypeCategory> result = typeCategoryRepository.findById(id);        assertTrue(result.isPresent());        assertEquals(typeCategoryModel, result.get());    }    @Test    @DisplayName("findById: Should return empty when entity not found")    void findById_NotFound_ReturnsEmpty() {        Long id = 999L;        when(queryJpaRepository.findById(id)).thenReturn(Optional.empty());        Optional<TypeCategory> result = typeCategoryRepository.findById(id);        assertTrue(result.isEmpty());    }}